a<-commandArgs(TRUE);repo<-normalizePath(if(length(a))a[1] else '.',winslash='/');source(file.path(repo,'methodology/contracts.R'))
d<-wf_read(file.path(repo,'templates/design.json'));tests<-list();add<-function(n,x)tests[[n]]<<-isTRUE(x)
add('valid design',!length(wf_design_errors(d,repo)))
for(k in wf_read(file.path(repo,'methodology/schema.json'))$required) {x<-d;x[[k]]<-NULL;add(paste('missing',k),length(wf_design_errors(x,repo))>0)}
x<-d;x$model$present<-'false';add('boolean type',length(wf_design_errors(x,repo))>0)
x<-d;x$source$kind<-'other';add('source enum',length(wf_design_errors(x,repo))>0)
x<-d;x$source$sql_applicability<-'REQUIRED';add('file applicability',length(wf_design_errors(x,repo))>0)
x<-d;x$safeguards[[1]]$applies<-TRUE;add('applicable plan required',length(wf_design_errors(x,repo))>0)
x$safeguards[[1]]$plan<-'Restrict inference to description';add('applicable plan accepted',!length(wf_design_errors(x,repo)))
x<-d;x$model<-list(present=TRUE,predictions_affect_decision=TRUE);add('model fields required',length(wf_design_errors(x,repo))>0)
x<-d;x$checkpoints[[1]]$numeric_missingness$amount_value$flag_field<-'absent';add('invalid missingness flag',length(wf_design_errors(x,repo))>0)
x<-d;x$checkpoints[[2]]$id<-x$checkpoints[[1]]$id;add('duplicate checkpoint',length(wf_design_errors(x,repo))>0)
cat('Schema:',sum(unlist(tests)),'/',length(tests),'passed\n');if(!all(unlist(tests)))stop(paste(names(tests)[!unlist(tests)],collapse=', '))
